definition.raw:
Suppose $f(x)$ is a fuzzy-number-valued function defined on the unbounded interval $[a, \infty)$. Then we define
\begin{eqnarray*}
\int_a^{\infty}f(x)dx=\lim_{t\to\infty}\int_a^{t}f(x)dx
\end{eqnarray*}
provided the limit on the right-hand side exists in $E^1$, in which case we say the integral converges and is equal to the value of limit. Otherwise, we say the integral diverges.

Let $f:[0,\infty)\rightarrow E^1$ be a continuous fuzzy-number-valued function  and $s(t)=\int\limits_0^{t}f(x)dx$. The Ces\`{a}ro means of $s(t)$ are defined by
\begin{eqnarray}\label{ortalama}
\sigma(t)=\frac{1}{t}\int_0^{t}s(u)du, \qquad t\in(0,\infty).
\end{eqnarray}
The integral
\begin{eqnarray}\label{integral}
\int_0^{\infty}f(x)dx
\end{eqnarray}
is said to be Ces\`{a}ro summable to a fuzzy number L if $\lim_{t\to \infty}\sigma(t)=L$.
The value of this limit is said to be the Ces\`{a}ro sum of the integral.

Let the fuzzy-number-valued function $f :[0,\infty)\to E^1$ be given as
\begin{eqnarray*}
(f(x))(t)=
\begin{cases}
\quad\frac{t}{2-\sin x}\quad, &\quad \textrm{if} \quad   0\leq t\leq 2-\sin x , \\[5pt]
2-\frac{t}{2-\sin x}\ , & \quad  \textrm{if} \quad  2-\sin x\leq t\leq 2(2-\sin x).

A continuous fuzzy-number-valued function $f:[0,\infty)\rightarrow E^1$ is said to be Ces\`{a}ro summable to a fuzzy number $L$ if
\begin{eqnarray*}
\lim_{t\to\infty}\frac{1}{t}\int_0^{t}f(x)dx=L.
\end{eqnarray*}

theorem.raw:
\cite{gv}\label{fint}
If the fuzzy-number-valued function $f:[a,b]\to E^1$ is continuous (with respect to the metric D) and for each $x\in[a,b]$, $f(x)$ has the parametric representation $$[f(x)]_{\alpha}=[f_{\alpha}^-(x), f_{\alpha}^+(x)],$$ then $\int\limits_a^bf(x)dx$ exists, belongs to $E^1$ and is parametrized by
$$\left[\int\limits_a^bf(x)dx\right]_{\alpha}=\left[\int\limits_a^bf_{\alpha}^-(x)dx, \int\limits_a^bf_{\alpha}^+(x)dx\right].$$

\label{maintheorem}
Let fuzzy-number-valued function $f:[0,\infty)\rightarrow E^1$ be continuous. If integral (\ref{integral}) is Ces\`{a}ro summable to a fuzzy number L, then it converges to L if and only if for every $\varepsilon>0$ there exist $t_0\geq 0$ and $\lambda>1$ such that for $t> t_0$
\begin{eqnarray}\label{*}
\frac{1}{\lambda t-t}\int_t^{\lambda t}s(x)dx \succeq s(t)-\overline{\varepsilon}
\end{eqnarray}
and another $0<\ell<1$ such that
\begin{eqnarray}\label{**}
\frac{1}{t-\ell t}\int_{\ell t}^{ t}s(x)dx \preceq s(t)+\overline{\varepsilon}.
\end{eqnarray}

\label{Landau}
Let $f$ be a continuous fuzzy-number-valued function on $[0,\infty)$. If there exist negative constant fuzzy number $u$ and a real number $x_0\geq 0$ such that
\begin{eqnarray}\label{one}
xf(x)\succeq u \quad \textrm{for}\quad x>x_0,
\end{eqnarray}
then fuzzy-number-valued function $s(t)=\int\limits_{0}^{t}f(x)dx$ is slowly decreasing.

If a continuous fuzzy-number-valued function $f$ is Ces\`{a}ro summable to a fuzzy number $L$, then $\lim_{t\to\infty}f(t)=L$ if and only if for every $\varepsilon>0$ there exist $t_0\geq 0$ and $\lambda>1$ such that for $t> t_0$
\begin{eqnarray*}
\frac{1}{\lambda t-t}\int_t^{\lambda t}f(x)dx \succeq f(t)-\overline{\varepsilon}
\end{eqnarray*}
and another $0<\ell<1$ such that
\begin{eqnarray*}
\frac{1}{t-\ell t}\int_{\ell t}^{ t}f(x)dx \preceq f(t)+\overline{\varepsilon}.
\end{eqnarray*}
\begin{theorem}
If a continuous fuzzy-number-valued function $f$ is Ces\`{a}ro summable to a fuzzy number $L$ and $f$ is slowly decreasing, then $\lim_{t\to\infty}f(t)=L$.

lemma.raw:
\label{epsilon}
Let $u,v,w,e\in E^1$ and $\varepsilon>0$. The following statements hold:
\begin{itemize}
  \item [(i)] $D(u,v)\leq\varepsilon$ if and only if $u-\overline{\varepsilon}\preceq v \preceq u+\overline{\varepsilon}$
  \item [(ii)] If $u\preceq v +\overline{\varepsilon}$ for every $\varepsilon>0$,  then $u\preceq v$.
  \item [(iii)] If $u\preceq v$ and $v\preceq w$, then $u\preceq w$.
   \item [(iv)] If  $u\preceq w$ and $v\preceq e$, then $u+v\preceq w+e$.
    \item [(v)] If  $u+w\preceq v+ w$ then $u\preceq v$.
\end{itemize}

\label{extra}
If $s$ be a continuous fuzzy-number-valued function then for every $\lambda>1$
\begin{eqnarray}\label{es1}
\frac{1}{\lambda t-t}\int_t^{\lambda t}s(x)dx + \frac{1}{\lambda-1}\sigma(t)=\sigma(\lambda t)+\frac{1}{\lambda-1}\sigma(\lambda t)
\end{eqnarray}
and for every $0<\ell<1$
\begin{eqnarray}\label{es2}
\frac{1}{t-\ell t}\int_{\ell t}^{ t}s(x)dx + \frac{\ell}{1-\ell}\sigma(\ell t)=\sigma( t)+\frac{\ell}{1-\ell}\sigma(t).
\end{eqnarray}

\label{lemma}
If integral (\ref{integral}) is Ces\`{a}ro summable to a fuzzy number $L$, then for every $\lambda>1$
\begin{eqnarray}\label{L1}
\lim_{t\to\infty}\frac{1}{\lambda t-t}\int_t^{\lambda t}s(x)dx=L
\end{eqnarray}
and for every $0<\ell<1$
\begin{eqnarray}\label{L2}
\lim_{t\to\infty}\frac{1}{t-\ell t}\int_{\ell t}^{ t}s(x)dx =L.
\end{eqnarray}

If the fuzzy-number-valued  function $s(x)$ is slowly decreasing, then for every $\varepsilon>0$ there exist $t_0\geq0$ and  $0<\lambda<1$ such that for every $t>t_0$
\begin{eqnarray}
s(t)\succeq s(x)-\overline{\varepsilon} \qquad \textrm{whenever}\qquad  \lambda t< x\leq t.
\end{eqnarray}

proposition.raw:
\cite{bede}
\label{p02} Let $u,v,w,z\in E^1$ and $k\in\mathbb{R}$. Then,
\begin{itemize}
\item [(i)] $(E^1,D)$ is a complete metric space.
\item [(ii)] $D(ku,kv)=|k|D(u,v)$.
\item [(iii)] $D(u+v,w+v)=D(u,w)$.
\item [(iv)] $D(u+v,w+z)\leq D(u,w)+D(v,z)$.
\item [(v)] $|D(u,\overline{0})-D(v,\overline{0})|\leq D(u,v)\leq
D(u,\overline{0})+D(v,\overline{0})$.
\end{itemize}

proof.raw:
{\it    Necessity}.
Let the integral (\ref{integral}) converge to $L$. Using inequality
\begin{eqnarray*}
D\left(\frac{1}{\lambda t-t}\int_t^{\lambda t}s(x)dx, s(t)\right)\leq D\left(\frac{1}{\lambda t-t}\int_t^{\lambda t}s(x)dx, L\right)+D(L,s(t)),
\end{eqnarray*}
if we consider the equality (\ref{L1}) in Lemma \ref{lemma} then for $\lambda>1$ we obtain
\begin{eqnarray*}
\lim_{t\to \infty}D\left(\frac{1}{\lambda t-t}\int_t^{\lambda t}s(x)dx, s(t)\right)=0.
\end{eqnarray*}
For $0<\ell<1$, validity of (\ref{**}) can also be obtained analogously by using the equality (\ref{L2}) of Lemma \ref{lemma}.

{\it    Sufficiency}. Assume that integral (\ref{integral}) is Ces\`{a}ro summable to $L$ and (\ref{*}), (\ref{**}) are satisfied. By (\ref{*}), there exist $t_1\geq 0$ and $\lambda>1$ such that for $t>t_1$
\begin{eqnarray*}
\frac{1}{\lambda t-t}\int_t^{\lambda t}s(x)dx \succeq s(t)-\frac{\overline{\varepsilon}}{3}\ \cdot
\end{eqnarray*}
Besides since
\begin{eqnarray*}
\lim\limits_{t\to \infty}D\left(\frac{1}{\lambda-1}\sigma(t), \frac{1}{\lambda-1}\sigma(\lambda t)\right)=0,
\end{eqnarray*}
there exists $t_2\geq 0$ such that for $t>t_2$
\begin{eqnarray*}
D\left(\frac{1}{\lambda-1}\sigma(t), \frac{1}{\lambda-1}\sigma(\lambda t)\right)\leq\frac{\varepsilon}{3}\cdot
\end{eqnarray*}
So by $(i)$ of Lemma \ref{epsilon} we get that
\begin{eqnarray*}
\frac{1}{\lambda-1}\sigma(t)- \frac{\overline{\varepsilon}}{3}\preceq \frac{1}{\lambda-1}\sigma(\lambda t)\preceq \frac{1}{\lambda-1}\sigma(t)+ \frac{\overline{\varepsilon}}{3}.
\end{eqnarray*}
Also, since $\lim\limits_{t\to \infty}\sigma(\lambda t)=L$, there exists $t_3\geq 0$ such that  $D(\sigma(\lambda t), L)\leq\frac{\varepsilon}{3}$ for $t> t_3$, meaning
\begin{eqnarray*}
L- \frac{\overline{\varepsilon}}{3}\preceq \sigma(\lambda t)\preceq L + \frac{\overline{\varepsilon}}{3}\cdot
\end{eqnarray*}
Then considering the equality (\ref{es1}) , there exists $t_4=\max\{t_1, t_2, t_3\}$ such that for $t> t_4$
\begin{eqnarray*}
s(t)-\frac{\overline{\varepsilon}}{3}+\frac{1}{\lambda-1}\sigma(t)\preceq L + \frac{\overline{\varepsilon}}{3}+\frac{1}{\lambda-1}\sigma(t)+ \frac{\overline{\varepsilon}}{3}\cdot
\end{eqnarray*}
So by $(v)$ of Lemma \ref{epsilon}, for $t> t_4$ we have
\begin{eqnarray}\label{epsilon1}
s(t)\preceq L + \overline{\varepsilon} .
\end{eqnarray}
On the other hand, if we consider the condition (\ref{**}),  equality (\ref{es2}), Lemma \ref{epsilon} and proceed in a similar way as that above, we get that there exists a $t_4^*\geq 0$ such that for $t> t_4^*$
\begin{eqnarray}\label{epsilon2}
s(t)\succeq L - \overline{\varepsilon}.
\end{eqnarray}
Then combining inequalities (\ref{epsilon1}) and (\ref{epsilon2}), we obtain
\begin{eqnarray*}
L - \overline{\varepsilon}\preceq s(t)\preceq L + \overline{\varepsilon}
\end{eqnarray*}
whenever $t>\max\{t_4,t_4^*\}$ and this completes the proof.

The proof of the lemma is done by contradiction method. Assume that the fuzzy-number-valued function $s(x)$ is slowly decreasing and there exists $\varepsilon_0>0$ such that for all $0<\lambda<1$ and $t_0\geq0$ there exist real numbers $x$ and $t>t_0$ for which
\begin{eqnarray}
s(t)\nsucceq s(x)-\overline{\varepsilon}_0\qquad \textrm{whenever}\qquad  \lambda t< x\leq t.
\end{eqnarray}
Therefore, there exists $\alpha_{\scriptscriptstyle 0}\in [0,1]$ such that
\begin{eqnarray}\label{cases}
s^-_{\alpha_{ 0}}(t)<s^-_{\alpha_{ 0}}(x)-\varepsilon_0 \quad or\quad s^+_{\alpha_0}(t)<s^+_{\alpha_0}(x)-\varepsilon_0.
\end{eqnarray}
At this point we recall the reformulated condition of M$\acute{o}$ricz \cite{moric1} for a slowly decreasing real valued function $f$ such that
\begin{eqnarray}\label{soldan}
\lim_{\lambda\rightarrow 1^{-}}\liminf_{t\rightarrow\infty}\min_{\lambda t\leq x\leq t}[f(t)-f(x)]\geq0.
\end{eqnarray}
No matter which case we choose in (\ref{cases}), one of the real valued functions $s^-_{\alpha_{ 0}}(t)$ and $s^+_{\alpha_0}(t)$ does not satisfy the condition (\ref{soldan}). So at least one of them is not slowly decreasing which contradicts the hypothesis that fuzzy-number-valued function $s(x)$ is slowly decreasing.

Let $ xf(x)\succeq u$ be satisfied under the given conditions on $u$ and $x_0$ in the theorem. Then for $x>x_0$ we have
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq u^-_{\alpha}\geq u^-_{0}\qquad ,\qquad xf_{\alpha}^+(x)\geq u^+_{\alpha}\geq u^+_{1}\geq u^-_{0}.
\end{eqnarray*}
For the sake of simplicity let take $u^-_{0}=-H$ where $H> 0$. Then
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq -H \Rightarrow f_{\alpha}^-(x)\geq -\frac{H}{x}\quad ,\quad
xf_{\alpha}^+(x)\geq -H \Rightarrow f_{\alpha}^+(x)\geq -\frac{H}{x}
\end{eqnarray*}
are satisfied. Then for $x_0< t<x\leq \lambda t$ when $\lambda>1$, we have
\begin{eqnarray*}
s_{\alpha}^-(x)-s_{\alpha}^-(t)=\int_t^xf_{\alpha}^-(u)du\geq -H\int_t^x\frac{du}{u}=-H\ln\frac{x}{t}\geq -H\ln \lambda
\end{eqnarray*}
and
\begin{eqnarray*}
s_{\alpha}^+(x)-s_{\alpha}^+(t)=\int_t^xf_{\alpha}^+(u)du\geq -H\int_t^x\frac{du}{u}=-H\ln\frac{x}{t}\geq -H\ln \lambda.
\end{eqnarray*}
Choosing $\lambda =e^{\varepsilon/H}$, we get the inequalities
\begin{eqnarray*}
s_{\alpha}^-(x)\geq s_{\alpha}^-(t)-\varepsilon\qquad ,\qquad
s_{\alpha}^+(x)\geq s_{\alpha}^+(t)-\varepsilon
\end{eqnarray*}
and then $s(x)\succeq s(t)-\overline{\varepsilon}$ holds whenever $x_0< t<x\leq \lambda t$.

example.raw:
Take the fuzzy-number-valued function  $f: [0,\infty) \to E^1$  such that
{\small\begin{eqnarray*}
(f(x))(t)=
\begin{cases}
(t-\cos x).(x+1)^2, & \quad \textrm{if} \quad  \cos x\leq t\leq \cos x+\frac{1}{(1+x)^2}, \\
2-(t-\cos x).(x+1)^2, &  \quad \textrm{if} \quad \cos x+\frac{1}{(1+x)^2}\leq t\leq \cos x+\frac{2}{(1+x)^2}, \\
0, & \qquad  \quad \textrm{otherwise}.
\end{cases}
\end{eqnarray*}}
Then $f$ is continuous and
{\small\begin{eqnarray*}
f^-_{\alpha}(x)=\cos x+\frac{\alpha}{(x+1)^2}\qquad\qquad &,&\qquad\qquad f^+_{\alpha}(x)=\cos x+\frac{2-\alpha}{(x+1)^2}\\
\int_{0}^{t}f_{\alpha}^-(x)dx=sint+\alpha\left(1-\frac{1}{t+1}\right)\quad &,& \quad \int_{0}^{t}f_{\alpha}^+(x)dx=sint+(2-\alpha)\left(1-\frac{1}{t+1}\right)
\end{eqnarray*}}
Obviously $\int\limits_{0}^{\infty}f(x)dx$ is divergent. To calculate Ces\`{a}ro mean, considering (\ref{ortalama}) we have
{\small\begin{eqnarray*}
\sigma_{\alpha}^-(t)&=&\frac{1}{t}\int_0^{t}s_{\alpha}^-(u)du=\frac{1}{t}\int_0^{t}\left(\int_0^{u}f_{\alpha}^-(x)dx\right)du=-\frac{\cos t}{t}+\frac{1}{t}+\alpha\left(1-\frac{\ln (t+1)}{t}\right)\\
\sigma_{\alpha}^+(t)&=&\frac{1}{t}\int_0^{t}s_{\alpha}^+(u)du=\frac{1}{t}\int_0^{t}\left(\int_0^{u}f_{\alpha}^+(x)dx\right)du=-\frac{\cos t}{t}+\frac{1}{t}+(2-\alpha)\left(1-\frac{\ln (t+1)}{t}\right).
\end{eqnarray*}}
So we get
\begin{eqnarray*}
\begin{rcases}
\lim_{t\to \infty}\sigma_{\alpha}^-(t)=\alpha \\
\lim_{t\to \infty}\sigma_{\alpha}^+(t)=2-\alpha\end{rcases}
\qquad [u]_{\alpha}=[\alpha, 2-\alpha] \qquad and \qquad \lim_{t\to \infty}D(\sigma(t),u)=0.
\end{eqnarray*}

Then $\int\limits_{0}^{\infty}f(x)dx$ is Ces\`{a}ro summable to fuzzy number $u$ such that
\begin{eqnarray*}
u(t)=
\begin{cases}
\ \ t &\quad \textrm{if} \quad  0\leq t\leq 1, \\
2-t &  \quad \textrm{if} \quad 1\leq t\leq 2, \\
\ \ 0 & \quad \quad  \ \  \textrm{otherwise}.
\end{cases}
\end{eqnarray*}

Let the fuzzy-number-valued function $f :[0,\infty)\to E^1$ be given as
\begin{eqnarray*}
(f(x))(t)=
\begin{cases}
\quad\frac{t}{2-\sin x}\quad, &\quad \textrm{if} \quad   0\leq t\leq 2-\sin x , \\[5pt]
2-\frac{t}{2-\sin x}\ , & \quad  \textrm{if} \quad  2-\sin x\leq t\leq 2(2-\sin x).
\end{cases}
\end{eqnarray*}
Then
\begin{eqnarray*}
f_{\alpha}^-(x)=(2-\sin x)\alpha \qquad \qquad , \qquad \quad f_{\alpha}^+(x)=(2-\sin x)(2-\alpha).
\end{eqnarray*}
Since $f_{\alpha}^{\pm}(x)\geq 0$ holds for each $\alpha \in [0,1]$ and $x>0$, we have
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq 0 \qquad , \qquad xf_{\alpha}^+(x)\geq 0 \quad
\end{eqnarray*}
which means that $xf(x)\succeq \overline{0}$. So $s(t)$ is slowly decreasing.

