\begin{lemma}\label{added}\cite{bede} The following statements hold:
\begin{itemize}
\item[(i)] $\overline{0} \in E^{1}$ is neutral element with respect to $+$, i.e., $u+\overline{0}=\overline{0}+u=u$ for all $u \in E^{1}$.
\item [(ii)] With respect to $\overline{0}$, none of $u \neq \overline{r}$, $r\in \mathbb{R}$
has opposite in $E^{1}.$
\item[(iii)] For any $a,b \in\mathbb{R}$ with $a, b \geq 0$ or $a,b \leq 0$ and any $u\in E^{1}$, we have
$(a + b) u = au + bu$. For general $a, b \in \mathbb{R}$, the above property does not hold.
\item[(iv)] For any $a \in \mathbb{R}$ and any $u, v \in E^{1}$, we have
$a (u+ v) = au + av.$
\item[(v)] For any $a, b \in \mathbb{R}$ and any $u \in E^{1}$, we have
$a (b u) = (a b) u.$
\end{itemize}
\end{lemma}
