\begin{example}
Let the fuzzy-number-valued function $f :[0,\infty)\to E^1$ be given as
\begin{eqnarray*}
(f(x))(t)=
\begin{cases}
\quad\frac{t}{2-\sin x}\quad, &\quad \textrm{if} \quad   0\leq t\leq 2-\sin x , \\[5pt]
2-\frac{t}{2-\sin x}\ , & \quad  \textrm{if} \quad  2-\sin x\leq t\leq 2(2-\sin x).
\end{cases}
\end{eqnarray*}
Then
\begin{eqnarray*}
f_{\alpha}^-(x)=(2-\sin x)\alpha \qquad \qquad , \qquad \quad f_{\alpha}^+(x)=(2-\sin x)(2-\alpha).
\end{eqnarray*}
Since $f_{\alpha}^{\pm}(x)\geq 0$ holds for each $\alpha \in [0,1]$ and $x>0$, we have
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq 0 \qquad , \qquad xf_{\alpha}^+(x)\geq 0 \quad
\end{eqnarray*}
which means that $xf(x)\succeq \overline{0}$. So $s(t)$ is slowly decreasing.
\end{example}
As a result of Theorem \ref{Landau} the following one-sided Tauberian condition is obtained.
\begin{corollary}
 If $f$ is a continuous fuzzy-number-valued function  such that integral (\ref{integral}) is Ces\`{a}ro summable to a fuzzy number L and condition (\ref{one}) is satisfied, then the integral (\ref{integral}) converges to $L$.
\end{corollary}
We note that one may extend Ces\`{a}ro summability method to continuous fuzzy-number-valued functions and give analogs of Theorem \ref{regular}--\ref{maintheorem}, Corollary \ref{maintheorem2} for Ces\`{a}ro summability of fuzzy-number-valued functions. The proofs are done identically by replacing integral function $s$ with general continuous fuzzy-number-valued function in corresponding proofs and hence omitted.
\begin{definition}
A continuous fuzzy-number-valued function $f:[0,\infty)\rightarrow E^1$ is said to be Ces\`{a}ro summable to a fuzzy number $L$ if
\begin{eqnarray*}
\lim_{t\to\infty}\frac{1}{t}\int_0^{t}f(x)dx=L.
\end{eqnarray*}
\end{definition}
\begin{theorem}
Let  $f$ be a continuous fuzzy-number-valued function. If \ $\lim_{t\to\infty}f(t)=L$, then $f$ is Ces\`{a}ro summable to fuzzy number $L$.
\end{theorem}
\begin{theorem}
If a continuous fuzzy-number-valued function $f$ is Ces\`{a}ro summable to a fuzzy number $L$, then $\lim_{t\to\infty}f(t)=L$ if and only if for every $\varepsilon>0$ there exist $t_0\geq 0$ and $\lambda>1$ such that for $t> t_0$
\begin{eqnarray*}
\frac{1}{\lambda t-t}\int_t^{\lambda t}f(x)dx \succeq f(t)-\overline{\varepsilon}
\end{eqnarray*}
and another $0<\ell<1$ such that
\begin{eqnarray*}
\frac{1}{t-\ell t}\int_{\ell t}^{ t}f(x)dx \preceq f(t)+\overline{\varepsilon}.
\end{eqnarray*}
\begin{theorem}
If a continuous fuzzy-number-valued function $f$ is Ces\`{a}ro summable to a fuzzy number $L$ and $f$ is slowly decreasing, then $\lim_{t\to\infty}f(t)=L$.
\end{theorem}

