We say a fuzzy number $u$ is negative if and only if $u(t)=0$ for all $t\geq 0$ (see \cite{negative}).\\
Combining the results of Lemma 6 in \cite{aytarfss1}, Lemma 5 in \cite{aytarinf3}, Lemma 3.4, Theorem 4.9 in \cite{Li}  and Lemma 14 in\cite{slowly}, following Lemma is obtained.
\begin{lemma}\label{epsilon}
Let $u,v,w,e\in E^1$ and $\varepsilon>0$. The following statements hold:
\begin{itemize}
  \item [(i)] $D(u,v)\leq\varepsilon$ if and only if $u-\overline{\varepsilon}\preceq v \preceq u+\overline{\varepsilon}$
  \item [(ii)] If $u\preceq v +\overline{\varepsilon}$ for every $\varepsilon>0$,  then $u\preceq v$.
  \item [(iii)] If $u\preceq v$ and $v\preceq w$, then $u\preceq w$.
   \item [(iv)] If  $u\preceq w$ and $v\preceq e$, then $u+v\preceq w+e$.
    \item [(v)] If  $u+w\preceq v+ w$ then $u\preceq v$.
\end{itemize}
\end{lemma}
\begin{definition}
A fuzzy-number-valued function $f:[a,b]\to E^1$ is said to be continuous at $x_0\in [a,b]$ if for each $\varepsilon>0$ there is a $\delta>0$ such that $D(f(x), f(x_0))<\varepsilon$ whenever $x\in [a,b]$ with $|x-x_0|<\delta$. If $f(x)$ is continuous at each $x\in [a,b]$, then we say $f(x)$ is continuous on $[a,b]$.
\end{definition}
\begin{definition}\cite{gv}
A fuzzy-valued function $f:[a,b]\to E^1$ is called Riemann integrable on $[a,b]$, if there exists $I\in E^1$ with the property : $\forall\varepsilon>0$, $\exists\delta>0$ such that for any division of $[a,b]$ $d : a=x_0<x_1<\cdots<x_n=b$ of norm $v(d)<\delta$, and for any points $\xi_i\in[x_i,x_{i+1}]\ i=\overline{0,n-1}$, we have $$D\left(\sum\limits_{i=0}^{n-1}f(\xi_i)(x_{i+1}-x_i), I\right)<\varepsilon.$$ Then $I=\int\limits_a^bf(x)dx$.
\end{definition}
\begin{theorem}\cite{gv}\label{fint}
If the fuzzy-number-valued function $f:[a,b]\to E^1$ is continuous (with respect to the metric D) and for each $x\in[a,b]$, $f(x)$ has the parametric representation $$[f(x)]_{\alpha}=[f_{\alpha}^-(x), f_{\alpha}^+(x)],$$ then $\int\limits_a^bf(x)dx$ exists, belongs to $E^1$ and is parametrized by
$$\left[\int\limits_a^bf(x)dx\right]_{\alpha}=\left[\int\limits_a^bf_{\alpha}^-(x)dx, \int\limits_a^bf_{\alpha}^+(x)dx\right].$$
\end{theorem}
Using the results of Anastassiou \cite{an} we have
\begin{theorem}\label{bessart}
If $f:[a,b]\to E^1$ and $g:[a,b]\to E^1$ are continuous then
\item [(i)] $\int\limits_a^b(\alpha f(x)+\beta g(x))dx=\alpha \int\limits_a^bf(x)dx+\beta\int\limits_a^bg(x)dx$ where $\alpha$ and $\beta$ are real numbers.
\item [(ii)] $\int\limits_a^bf(x)dx=\int\limits_a^cf(x)dx+\int\limits_c^bf(x)dx$ where $a<c<b$.
\item [(iii)]The function $F :[a,b]\to \mathbb{R_+}$ defined by $F(x)=D(f(x),g(x))$ is continuous on $[a, b]$ and\\ $$D\left(\int\limits_a^bf(x)dx,\int\limits_a^bg(x)dx \right)\leq \int\limits_a^bF(x)dx.$$
\item [(iv)] $\int\limits_a^xf(t)dt$ is a continuous function in $x\in[a,b]$.
\item [(v)] $\int\limits_a^b f(x)dx \preceq \int\limits_a^b g(x)dx $  whenever   $f(x)\preceq g(x)$ for all $x\in[a,b]$.
\end{theorem}
\begin{definition}
Suppose $f(x)$ is a fuzzy-number-valued function defined on the unbounded interval $[a, \infty)$. Then we define
\begin{eqnarray*}
\int_a^{\infty}f(x)dx=\lim_{t\to\infty}\int_a^{t}f(x)dx
\end{eqnarray*}
provided the limit on the right-hand side exists in $E^1$, in which case we say the integral converges and is equal to the value of limit. Otherwise, we say the integral diverges.
\end{definition}
\section{Main Results}
\begin{definition}
Let $f:[0,\infty)\rightarrow E^1$ be a continuous fuzzy-number-valued function  and $s(t)=\int\limits_0^{t}f(x)dx$. The Ces\`{a}ro means of $s(t)$ are defined by
\begin{eqnarray}\label{ortalama}
\sigma(t)=\frac{1}{t}\int_0^{t}s(u)du, \qquad t\in(0,\infty).
\end{eqnarray}
The integral
\begin{eqnarray}\label{integral}
\int_0^{\infty}f(x)dx
\end{eqnarray}
is said to be Ces\`{a}ro summable to a fuzzy number L if $\lim_{t\to \infty}\sigma(t)=L$.
The value of this limit is said to be the Ces\`{a}ro sum of the integral.
\end{definition}
\begin{theorem}\label{regular}
If the integral (\ref{integral}) converges to a fuzzy number L, then (\ref{ortalama}) also converges to L.
\end{theorem}
\begin{proof}
Let $$\lim\limits_{t\to \infty}s(t)=\int_0^{\infty}f(x)dx=L$$ for  some $L\in E^1$. Then given any $\varepsilon>0 $ there exists $t_0>0$ such that $D(s(t), L)<\frac{\varepsilon}{2}$ whenever $t\geq t_0$ and there exists $M>0$ such that $D(s(t), L)<M$ whenever $t< t_0$. So we have
\begin{eqnarray*}
D(\sigma(t),L)&=&D\left(\frac{1}{t}\int_0^ts(u)du, L\right)
\\&=&
D\left(\frac{1}{t}\int_0^ts(u)du,\frac{1}{t}\int_0^tLdu\right)
\\&=&
\frac{1}{t}D\left(\int_0^ts(u)du, \int_0^tLdu\right)
\\&\leq &
\frac{1}{t}\int_0^tD(s(u),L)du
\\&=&
\frac{1}{t}\int_0^{t_0}D(s(u),L)du+ \frac{1}{t}\int_{t_0}^tD(s(u),L)du
\\&\leq &
\frac{t_0M}{t}+\frac{\varepsilon}{2}\frac{(t-t_0)}{t}< \frac{t_0M}{t}+ \frac{\varepsilon}{2}
\end{eqnarray*}
Since $\lim\limits_{t\to\infty}\frac{t_0M}{t}=0$, there exists $t_1>0$ such that $\left|\frac{t_0M}{t}\right|<\frac{\varepsilon}{2}$ whenever $t\geq t_1$. So there exists $t_2=\max\{t_0,t_1\}$ such that $$D(\sigma(t),L)<\varepsilon$$ whenever $t\geq t_2$. This completes the proof.

\begin{definition}
A fuzzy-number-valued function $f:[a,b]\to E^1$ is said to be continuous at $x_0\in [a,b]$ if for each $\varepsilon>0$ there is a $\delta>0$ such that $D(f(x), f(x_0))<\varepsilon$ whenever $x\in [a,b]$ with $|x-x_0|<\delta$. If $f(x)$ is continuous at each $x\in [a,b]$, then we say $f(x)$ is continuous on $[a,b]$.
\end{definition}
\begin{definition}\cite{gv}
A fuzzy-valued function $f:[a,b]\to E^1$ is called Riemann integrable on $[a,b]$, if there exists $I\in E^1$ with the property : $\forall\varepsilon>0$, $\exists\delta>0$ such that for any division of $[a,b]$ $d : a=x_0<x_1<\cdots<x_n=b$ of norm $v(d)<\delta$, and for any points $\xi_i\in[x_i,x_{i+1}]\ i=\overline{0,n-1}$, we have $$D\left(\sum\limits_{i=0}^{n-1}f(\xi_i)(x_{i+1}-x_i), I\right)<\varepsilon.$$ Then $I=\int\limits_a^bf(x)dx$.
\end{definition}

\begin{definition}
Suppose $f(x)$ is a fuzzy-number-valued function defined on the unbounded interval $[a, \infty)$. Then we define
\begin{eqnarray*}
\int_a^{\infty}f(x)dx=\lim_{t\to\infty}\int_a^{t}f(x)dx
\end{eqnarray*}
provided the limit on the right-hand side exists in $E^1$, in which case we say the integral converges and is equal to the value of limit. Otherwise, we say the integral diverges.
\end{definition}

\begin{proof}
Let $$\lim\limits_{t\to \infty}s(t)=\int_0^{\infty}f(x)dx=L$$ for  some $L\in E^1$. Then given any $\varepsilon>0 $ there exists $t_0>0$ such that $D(s(t), L)<\frac{\varepsilon}{2}$ whenever $t\geq t_0$ and there exists $M>0$ such that $D(s(t), L)<M$ whenever $t< t_0$. So we have
\begin{eqnarray*}
D(\sigma(t),L)&=&D\left(\frac{1}{t}\int_0^ts(u)du, L\right)
\\&=&
D\left(\frac{1}{t}\int_0^ts(u)du,\frac{1}{t}\int_0^tLdu\right)
\\&=&
\frac{1}{t}D\left(\int_0^ts(u)du, \int_0^tLdu\right)
\\&\leq &
\frac{1}{t}\int_0^tD(s(u),L)du
\\&=&
\frac{1}{t}\int_0^{t_0}D(s(u),L)du+ \frac{1}{t}\int_{t_0}^tD(s(u),L)du
\\&\leq &
\frac{t_0M}{t}+\frac{\varepsilon}{2}\frac{(t-t_0)}{t}< \frac{t_0M}{t}+ \frac{\varepsilon}{2}
\end{eqnarray*}
Since $\lim\limits_{t\to\infty}\frac{t_0M}{t}=0$, there exists $t_1>0$ such that $\left|\frac{t_0M}{t}\right|<\frac{\varepsilon}{2}$ whenever $t\geq t_1$. So there exists $t_2=\max\{t_0,t_1\}$ such that $$D(\sigma(t),L)<\varepsilon$$ whenever $t\geq t_2$. This completes the proof.
\end{proof}
By the following example it can be easily seen that the converse statement of Theorem \ref{regular} is not true in general.
\begin{example}
Take the fuzzy-number-valued function  $f: [0,\infty) \to E^1$  such that
{\small\begin{eqnarray*}
(f(x))(t)=
\begin{cases}
(t-\cos x).(x+1)^2, & \quad \textrm{if} \quad  \cos x\leq t\leq \cos x+\frac{1}{(1+x)^2}, \\
2-(t-\cos x).(x+1)^2, &  \quad \textrm{if} \quad \cos x+\frac{1}{(1+x)^2}\leq t\leq \cos x+\frac{2}{(1+x)^2}, \\
0, & \qquad  \quad \textrm{otherwise}.
\end{cases}
\end{eqnarray*}}
Then $f$ is continuous and
{\small\begin{eqnarray*}
f^-_{\alpha}(x)=\cos x+\frac{\alpha}{(x+1)^2}\qquad\qquad &,&\qquad\qquad f^+_{\alpha}(x)=\cos x+\frac{2-\alpha}{(x+1)^2}\\
\int_{0}^{t}f_{\alpha}^-(x)dx=sint+\alpha\left(1-\frac{1}{t+1}\right)\quad &,& \quad \int_{0}^{t}f_{\alpha}^+(x)dx=sint+(2-\alpha)\left(1-\frac{1}{t+1}\right)
\end{eqnarray*}}
Obviously $\int\limits_{0}^{\infty}f(x)dx$ is divergent. To calculate Ces\`{a}ro mean, considering (\ref{ortalama}) we have
