\end{remark}

\begin{proof}
The proof of the lemma is done by contradiction method. Assume that the fuzzy-number-valued function $s(x)$ is slowly decreasing and there exists $\varepsilon_0>0$ such that for all $0<\lambda<1$ and $t_0\geq0$ there exist real numbers $x$ and $t>t_0$ for which
\begin{eqnarray}
s(t)\nsucceq s(x)-\overline{\varepsilon}_0\qquad \textrm{whenever}\qquad  \lambda t< x\leq t.
\end{eqnarray}
Therefore, there exists $\alpha_{\scriptscriptstyle 0}\in [0,1]$ such that
\begin{eqnarray}\label{cases}
s^-_{\alpha_{ 0}}(t)<s^-_{\alpha_{ 0}}(x)-\varepsilon_0 \quad or\quad s^+_{\alpha_0}(t)<s^+_{\alpha_0}(x)-\varepsilon_0.
\end{eqnarray}
At this point we recall the reformulated condition of M$\acute{o}$ricz \cite{moric1} for a slowly decreasing real valued function $f$ such that
\begin{eqnarray}\label{soldan}
\lim_{\lambda\rightarrow 1^{-}}\liminf_{t\rightarrow\infty}\min_{\lambda t\leq x\leq t}[f(t)-f(x)]\geq0.
\end{eqnarray}
No matter which case we choose in (\ref{cases}), one of the real valued functions $s^-_{\alpha_{ 0}}(t)$ and $s^+_{\alpha_0}(t)$ does not satisfy the condition (\ref{soldan}). So at least one of them is not slowly decreasing which contradicts the hypothesis that fuzzy-number-valued function $s(x)$ is slowly decreasing.
\end{proof}

It is clear that if function $s$ is slowly decreasing then conditions (\ref{*}) and (\ref{**}) are satisfied by $(i)$ and $(v)$ of Theorem \ref{bessart}.  So next corollary immediately follows:

\begin{proof}
Let $ xf(x)\succeq u$ be satisfied under the given conditions on $u$ and $x_0$ in the theorem. Then for $x>x_0$ we have
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq u^-_{\alpha}\geq u^-_{0}\qquad ,\qquad xf_{\alpha}^+(x)\geq u^+_{\alpha}\geq u^+_{1}\geq u^-_{0}.
\end{eqnarray*}
For the sake of simplicity let take $u^-_{0}=-H$ where $H> 0$. Then
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq -H \Rightarrow f_{\alpha}^-(x)\geq -\frac{H}{x}\quad ,\quad
xf_{\alpha}^+(x)\geq -H \Rightarrow f_{\alpha}^+(x)\geq -\frac{H}{x}
\end{eqnarray*}
are satisfied. Then for $x_0< t<x\leq \lambda t$ when $\lambda>1$, we have
\begin{eqnarray*}
s_{\alpha}^-(x)-s_{\alpha}^-(t)=\int_t^xf_{\alpha}^-(u)du\geq -H\int_t^x\frac{du}{u}=-H\ln\frac{x}{t}\geq -H\ln \lambda
\end{eqnarray*}
and
\begin{eqnarray*}
s_{\alpha}^+(x)-s_{\alpha}^+(t)=\int_t^xf_{\alpha}^+(u)du\geq -H\int_t^x\frac{du}{u}=-H\ln\frac{x}{t}\geq -H\ln \lambda.
\end{eqnarray*}
Choosing $\lambda =e^{\varepsilon/H}$, we get the inequalities
\begin{eqnarray*}
s_{\alpha}^-(x)\geq s_{\alpha}^-(t)-\varepsilon\qquad ,\qquad
s_{\alpha}^+(x)\geq s_{\alpha}^+(t)-\varepsilon
\end{eqnarray*}
and then $s(x)\succeq s(t)-\overline{\varepsilon}$ holds whenever $x_0< t<x\leq \lambda t$.
\end{proof}
\begin{example}
Let the fuzzy-number-valued function $f :[0,\infty)\to E^1$ be given as
\begin{eqnarray*}
(f(x))(t)=
\begin{cases}
\quad\frac{t}{2-\sin x}\quad, &\quad \textrm{if} \quad   0\leq t\leq 2-\sin x , \\[5pt]
2-\frac{t}{2-\sin x}\ , & \quad  \textrm{if} \quad  2-\sin x\leq t\leq 2(2-\sin x).
\end{cases}
\end{eqnarray*}
Then
\begin{eqnarray*}
f_{\alpha}^-(x)=(2-\sin x)\alpha \qquad \qquad , \qquad \quad f_{\alpha}^+(x)=(2-\sin x)(2-\alpha).
\end{eqnarray*}
Since $f_{\alpha}^{\pm}(x)\geq 0$ holds for each $\alpha \in [0,1]$ and $x>0$, we have
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq 0 \qquad , \qquad xf_{\alpha}^+(x)\geq 0 \quad
\end{eqnarray*}
which means that $xf(x)\succeq \overline{0}$. So $s(t)$ is slowly decreasing.
\end{example}
As a result of Theorem \ref{Landau} the following one-sided Tauberian condition is obtained.

We note that one may extend Ces\`{a}ro summability method to continuous fuzzy-number-valued functions and give analogs of Theorem \ref{regular}--\ref{maintheorem}, Corollary \ref{maintheorem2} for Ces\`{a}ro summability of fuzzy-number-valued functions. The proofs are done identically by replacing integral function $s$ with general continuous fuzzy-number-valued function in corresponding proofs and hence omitted.
\begin{definition}
A continuous fuzzy-number-valued function $f:[0,\infty)\rightarrow E^1$ is said to be Ces\`{a}ro summable to a fuzzy number $L$ if
\begin{eqnarray*}
\lim_{t\to\infty}\frac{1}{t}\int_0^{t}f(x)dx=L.
\end{eqnarray*}
\end{definition}

